(function(){
  const esc=v=>String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
  const now=()=>new Date().toISOString();
  const clock=v=>new Date(v||Date.now()).toLocaleTimeString("ar-SA",{hour:"2-digit",minute:"2-digit"});
  const stage=p=>p>=100?"مكتمل":p>=82?"المراجعة":p>=60?"إعداد التقرير":p>=35?"التحليل":"جمع البيانات";
  state.rules=state.rules||[
    {id:"spend",scope:"الشركة",text:"ممنوع أي إنفاق دون موافقة نواف الصريحة",level:"FINANCIAL",locked:true},
    {id:"mueen-content",scope:"مُعِين",text:"تغييرات المحتوى الديني تتطلب مراجعة الرئيس التنفيذي",level:"APPROVAL_REQUIRED",locked:true}
  ];
  state.requests=state.requests||[];
  state.activities=state.activities.map((a,i)=>Object.assign({id:"legacy-"+i,createdAt:now()},a));
  state.tasks.forEach(t=>{t.status=t.status||(t.progress>=100?"COMPLETED":"ACTIVE");t.history=t.history||[{at:now(),text:"تمت مزامنة المهمة مع حالة الشركة"}];});
  state.reports.forEach(r=>{r.createdAt=r.createdAt||now();r.updatedAt=r.updatedAt||r.createdAt;r.history=r.history||[{at:r.createdAt,stage:r.stage,progress:r.progress}];});
  state.employees.forEach(e=>{e.permissions=e.permissions||"AUTO_INTERNAL";e.history=e.history||state.activities.filter(a=>a.text.includes(e.name)).map(a=>({at:a.createdAt,text:a.text}));});
  save();

  function event(text,kind,links){const a={id:"ev-"+Date.now()+Math.random().toString(16).slice(2),text,kind:kind||"SIM",createdAt:now(),links:links||{}};state.activities.unshift(a);if(a.links.employee){const e=emp(a.links.employee);if(e){e.history=e.history||[];e.history.unshift({at:a.createdAt,text:a.text});}}return a;}
  function closeButton(){return '<button class="dialog-close" data-close>إغلاق</button>';}
  function open(html,wide=true){modal('<div class="'+(wide?'dialog-wide':'')+'">'+html+'</div>');document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$("#modal").classList.remove("open"));}
  function taskView(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;const e=emp(t.employee),p=pr(t.project),r=state.reports.find(x=>x.task===id||x.author===t.employee&&x.project===t.project);open('<div class="workspace-head"><div><h2>'+esc(t.title)+'</h2><p class="muted">'+esc(p.name)+' · '+esc(e.name)+' · '+esc(e.department)+'</p></div><div class="workspace-badges"><span class="badge real">حالة مرتبطة</span><span class="badge">'+esc(t.status)+'</span>'+closeButton()+'</div></div><div class="detail-grid"><div class="detail-box"><b>'+t.progress+'%</b><small>التقدم</small></div><div class="detail-box"><b>'+esc(e.status)+'</b><small>حالة الموظف</small></div><div class="detail-box"><b>'+esc(r?r.stage:"لا يوجد")+'</b><small>المخرج</small></div></div><div class="bar"><i style="width:'+t.progress+'%"></i></div><h3>خط المهمة</h3><div class="timeline">'+(t.history||[]).map(h=>'<div class="timeline-item"><time>'+clock(h.at)+'</time><i></i><span>'+esc(h.text)+'</span></div>').join('')+'</div>');}

  const originalEmployee=window.employee;
  window.employee=function(id){if(!id)return originalEmployee();const e=emp(id);if(!e)return;const tasks=state.tasks.filter(t=>t.employee===id),reports=state.reports.filter(r=>r.author===id),history=e.history||[];open('<div class="workspace-head"><div><h2>مساحة '+esc(e.name)+'</h2><p class="muted">'+esc(e.role)+' · '+esc(e.department)+'</p></div><div class="workspace-badges"><span class="badge '+(e.status==="WAITING_APPROVAL"?'wait':'real')+'">'+esc(status(e.status))+'</span>'+closeButton()+'</div></div><div class="detail-grid"><div class="detail-box"><b>'+esc(e.productivity)+'%</b><small>الإنتاجية</small></div><div class="detail-box"><b>'+tasks.filter(t=>t.progress===100).length+'</b><small>مهام مكتملة</small></div><div class="detail-box"><b>'+reports.length+'</b><small>تقارير محفوظة</small></div></div><div class="split"><section><h3>العمل الحالي</h3>'+tasks.map(t=>'<div class="report click-task" data-task="'+esc(t.id)+'"><b>'+esc(t.title)+'</b><small>'+t.progress+'% · '+esc(t.status)+'</small><div class="bar"><i style="width:'+t.progress+'%"></i></div></div>').join('')+'<h3>سجل العمل</h3><div class="timeline">'+history.map(h=>'<div class="timeline-item"><time>'+clock(h.at)+'</time><i></i><span>'+esc(h.text)+'</span></div>').join('')+'</div></section><section><h3>إدارة الموظف</h3><form id="edit-employee"><label>الاسم</label><input name="name" value="'+esc(e.name)+'" required><label>الدور</label><input name="role" value="'+esc(e.role)+'"><label>القسم</label><input name="department" value="'+esc(e.department)+'"><label>الحالة</label><select name="status">'+["WORKING","RESEARCHING","COLLABORATING","IDLE","REVIEWING","WAITING_APPROVAL","COMPLETED"].map(s=>'<option '+(s===e.status?'selected':'')+'>'+s+'</option>').join('')+'</select><label>الصلاحيات</label><select name="permissions"><option '+(e.permissions==='AUTO_INTERNAL'?'selected':'')+'>AUTO_INTERNAL</option><option '+(e.permissions==='APPROVAL_REQUIRED'?'selected':'')+'>APPROVAL_REQUIRED</option></select><label>التعليمات</label><textarea name="instructions">'+esc(e.instructions)+'</textarea><button class="primary">حفظ السجل الموحد</button></form></section></div>');document.querySelectorAll('[data-task]').forEach(x=>x.onclick=()=>taskView(x.dataset.task));$("#edit-employee").onsubmit=x=>{x.preventDefault();Object.assign(e,Object.fromEntries(new FormData(x.target)));event('تم تحديث سجل '+e.name,'REAL',{employee:e.id});save();render();toast('تم تحديث الموظف في جميع المساحات');};};

  window.project=function(id){const p=pr(id),tasks=state.tasks.filter(t=>t.project===id),reports=state.reports.filter(r=>r.project===id),decs=state.decisions.filter(d=>d.project===p.name),acts=state.activities.filter(a=>a.links&&a.links.project===id||a.text.includes(p.name)).slice(0,8);open('<div class="workspace-head"><div><h2>مشروع '+esc(p.name)+'</h2><p class="muted">'+esc(p.phase)+' · صحة المشروع '+p.progress+'%</p></div>'+closeButton()+'</div><div class="detail-grid"><div class="detail-box"><b>'+p.progress+'%</b><small>التقدم</small></div><div class="detail-box"><b>'+tasks.filter(t=>t.progress<100).length+'</b><small>مهام نشطة</small></div><div class="detail-box"><b>'+decs.length+'</b><small>قرارات معلقة</small></div></div><div class="split"><section><h3>المهام</h3>'+tasks.map(t=>'<div class="report click-task" data-task="'+t.id+'"><b>'+esc(t.title)+'</b><small>'+esc(emp(t.employee).name)+' · '+t.progress+'%</small><div class="bar"><i style="width:'+t.progress+'%"></i></div></div>').join('')+'</section><section><h3>التقارير</h3>'+reports.map(r=>'<div class="report click-task" data-open-report="'+r.id+'"><b>'+esc(r.title)+'</b><small>'+esc(r.stage)+' · '+r.progress+'%</small></div>').join('')+'<h3>العوائق</h3><p>'+esc(p.issues.join('، ')||'لا توجد عوائق')+'</p></section></div><h3>آخر التغييرات</h3><div class="timeline">'+acts.map(a=>'<div class="timeline-item"><time>'+clock(a.createdAt)+'</time><i></i><span>'+esc(a.text)+'</span></div>').join('')+'</div>');document.querySelectorAll('[data-task]').forEach(x=>x.onclick=()=>taskView(x.dataset.task));document.querySelectorAll('[data-open-report]').forEach(x=>x.onclick=()=>report(x.dataset.openReport));};

  window.department=function(name){const es=state.employees.filter(e=>e.department===name),tasks=state.tasks.filter(t=>es.some(e=>e.id===t.employee)),incoming=state.requests.filter(r=>r.to===name);open('<div class="workspace-head"><div><h2>قسم '+esc(name)+'</h2><p class="muted">مساحة عمل مترابطة مع المشاريع والطلبات</p></div>'+closeButton()+'</div><div class="detail-grid"><div class="detail-box"><b>'+es.length+'</b><small>فريق القسم</small></div><div class="detail-box"><b>'+tasks.filter(t=>t.progress<100).length+'</b><small>عبء نشط</small></div><div class="detail-box"><b>'+incoming.length+'</b><small>طلبات واردة</small></div></div><div class="split"><section><h3>الموظفون</h3>'+es.map(e=>'<div class="report click-task" data-open-emp="'+e.id+'"><b>'+esc(e.name)+'</b><small>'+esc(e.task)+' · '+esc(status(e.status))+'</small></div>').join('')+'</section><section><h3>طلبات التعاون</h3>'+(incoming.length?incoming.map(r=>'<div class="report"><b>'+esc(r.title)+'</b><small>'+esc(r.from)+' · '+esc(r.status)+'</small></div>').join(''):'<div class="empty-state">لا توجد طلبات جديدة</div>')+'</section></div>');document.querySelectorAll('[data-open-emp]').forEach(x=>x.onclick=()=>employee(x.dataset.openEmp));};

  window.report=function(id){const r=state.reports.find(x=>x.id===id),e=emp(r.author),p=pr(r.project);open('<div class="workspace-head"><div><h2>'+esc(r.title)+'</h2><p class="muted">'+esc(e.name)+' · '+esc(p.name)+' · '+clock(r.createdAt)+'</p></div><div class="workspace-badges"><span class="badge">'+esc(r.stage)+'</span>'+closeButton()+'</div></div><div class="bar"><i style="width:'+r.progress+'%"></i></div><h3>المحتوى المحفوظ</h3><div class="report"><p>'+esc(r.content)+'</p></div><h3>دورة التقرير</h3><div class="timeline">'+(r.history||[]).map(h=>'<div class="timeline-item"><time>'+clock(h.at)+'</time><i></i><span>'+esc(h.stage)+' — '+h.progress+'%</span></div>').join('')+'</div><p class="muted">🔵 مخرج داخلي. لا يمثل إجراءً خارجيًا ما لم يُعلّم كإجراء متصل.</p>');};

  window.rules=function(){open('<div class="workspace-head"><div><h2>دستور الشركة</h2><p class="muted">قواعد تنفيذية تتحقق منها تدفقات العمل</p></div>'+closeButton()+'</div><form id="rules-form">'+state.rules.map(r=>'<div class="rule-row"><input name="text-'+r.id+'" value="'+esc(r.text)+'" '+(r.locked?'readonly':'')+'><select name="level-'+r.id+'"><option '+(r.level==='AUTO'?'selected':'')+'>AUTO</option><option '+(r.level==='APPROVAL_REQUIRED'?'selected':'')+'>APPROVAL_REQUIRED</option><option '+(r.level==='FINANCIAL'?'selected':'')+'>FINANCIAL</option></select><span class="badge '+(r.locked?'wait':'')+'">'+esc(r.scope)+(r.locked?' · ثابت':'')+'</span></div>').join('')+'<div class="detail-actions"><button type="button" id="add-rule">إضافة قاعدة</button><button class="primary">حفظ الدستور</button></div></form>');$("#add-rule").onclick=()=>{state.rules.push({id:'rule-'+Date.now(),scope:'الشركة',text:'قاعدة جديدة',level:'APPROVAL_REQUIRED',locked:false});save();rules();};$("#rules-form").onsubmit=x=>{x.preventDefault();const f=new FormData(x.target);state.rules.forEach(r=>{if(!r.locked)r.text=f.get('text-'+r.id);r.level=f.get('level-'+r.id);});event('تم تحديث دستور الشركة','REAL');save();render();toast('تم حفظ القواعد التنفيذية');};};

  window.analytics=function(){const active=state.tasks.filter(t=>t.progress<100).length,done=state.tasks.length-active,reportCount=state.reports.length,approvalAge=state.decisions.length?Math.round(state.decisions.length*6):0;open('<div class="workspace-head"><div><h2>تحليلات الشركة</h2><p class="muted">محسوبة لحظيًا من الحالة المشتركة</p></div>'+closeButton()+'</div><div class="detail-grid"><div class="detail-box"><b>'+avg()+'%</b><small>إنتاجية الفريق</small></div><div class="detail-box"><b>'+active+'</b><small>مهام نشطة</small></div><div class="detail-box"><b>'+done+'</b><small>مهام مكتملة</small></div><div class="detail-box"><b>'+reportCount+'</b><small>تقارير منتجة</small></div><div class="detail-box"><b>'+state.requests.length+'</b><small>تعاون بين الأقسام</small></div><div class="detail-box"><b>'+approvalAge+' س</b><small>زمن الموافقات التقديري</small></div></div>');};

  window.approve=function(action,id){const d=state.decisions.find(x=>x.id===id);if(!d)return;if(action==='approve'){state.decisions=state.decisions.filter(x=>x.id!==id);let t=state.tasks.find(x=>x.id==='t1');t.progress=Math.max(t.progress,55);t.status='ACTIVE';t.history.unshift({at:now(),text:'اعتمد نواف التنفيذ وبدأت مرحلة إعداد الموجز'});const omar=emp('omar');omar.status='WORKING';omar.task='موجز الحملة للتصميم';let design=state.tasks.find(x=>x.title==='تصاميم حملة قدّها');if(!design){design={id:'design-'+Date.now(),title:'تصاميم حملة قدّها',employee:'lian',project:'q',progress:8,status:'ACTIVE',history:[{at:now(),text:'استلمت ليان طلب التصميم من قسم التسويق'}]};state.tasks.push(design);}const lian=emp('lian');lian.status='COLLABORATING';lian.task=design.title;state.requests.push({id:'req-'+Date.now(),title:'تصميم حملة قدّها',from:'التسويق',to:'التصميم',status:'قيد التنفيذ',task:design.id,createdAt:now()});event('نواف اعتمد: '+d.title,'REAL',{employee:'omar',project:'q',task:'t1'});event('تم إرسال النتائج إلى قسم التصميم','SIM',{employee:'lian',project:'q',task:design.id});toast('تم الاعتماد وبدأ مسار التنفيذ');}else if(action==='changes'){d.status='CHANGES_REQUESTED';event('نواف طلب تعديلات على '+d.title,'APPROVAL',{project:'q'});toast('أعيد القرار لصاحب الطلب');}else{state.decisions=state.decisions.filter(x=>x.id!==id);event('نواف رفض: '+d.title,'REAL',{project:'q'});toast('تم إيقاف التدفق بأمان');}save();render();};
  window.advance=function(){const t=state.tasks.find(t=>t.progress<100&&emp(t.employee)&&emp(t.employee).status!=="WAITING_APPROVAL");if(!t)return toast('لا توجد مهمة قابلة للتقدم');t.progress=Math.min(100,t.progress+18);t.status=t.progress===100?'COMPLETED':'ACTIVE';t.history=t.history||[];t.history.unshift({at:now(),text:'تقدمت المهمة إلى '+t.progress+'%'});const e=emp(t.employee);e.progress=t.progress;e.status=t.progress===100?'COMPLETED':(e.id==='noura'?'REPORTING':'WORKING');event(e.name+' حدّث '+t.title+' إلى '+t.progress+'%','SIM',{employee:e.id,project:t.project,task:t.id});let r=state.reports.find(r=>r.task===t.id||r.author===e.id&&r.project===t.project);if(!r&&t.progress>=60){r={id:'r-'+Date.now(),title:'مخرجات '+t.title,author:e.id,project:t.project,task:t.id,stage:stage(t.progress),progress:t.progress,content:'نتائج داخلية محفوظة ناتجة عن سير المهمة، جاهزة للتوسعة والمراجعة.',createdAt:now(),updatedAt:now(),history:[]};state.reports.push(r);event(e.name+' أنشأ مخرجًا محفوظًا','SIM',{employee:e.id,project:t.project,task:t.id,report:r.id});}if(r){r.task=r.task||t.id;r.progress=t.progress;r.stage=stage(t.progress);r.updatedAt=now();r.history=r.history||[];r.history.unshift({at:r.updatedAt,stage:r.stage,progress:r.progress});}if(t.progress===100)event(e.name+' أكمل المهمة وأصبح التقرير متاحًا','SIM',{employee:e.id,project:t.project,task:t.id,report:r&&r.id});const p=pr(t.project);p.progress=Math.round(state.tasks.filter(x=>x.project===p.id).reduce((n,x)=>n+x.progress,0)/state.tasks.filter(x=>x.project===p.id).length);save();render();toast('تقدم '+t.title+': '+t.progress+'%');};

  const oldBind=window.bind;window.bind=function(){oldBind();const q=document.querySelector('.search');if(q){q.addEventListener('input',()=>{document.querySelector('.search-results')?.remove();const v=q.value.trim();if(!v)return;const people=state.employees.filter(e=>(e.name+e.role+e.department).includes(v)).slice(0,4),projects=state.projects.filter(p=>p.name.includes(v));const box=document.createElement('div');box.className='search-results';box.innerHTML=(people.map(e=>'<button data-search-emp="'+e.id+'"><span>'+esc(e.name)+'</span><small>'+esc(e.role)+'</small></button>').join('')+projects.map(p=>'<button data-search-project="'+p.id+'"><span>'+esc(p.name)+'</span><small>مشروع</small></button>').join(''))||'<div class="empty-state">لا توجد نتائج</div>';document.querySelector('.topbar').appendChild(box);box.querySelectorAll('[data-search-emp]').forEach(x=>x.onclick=()=>employee(x.dataset.searchEmp));box.querySelectorAll('[data-search-project]').forEach(x=>x.onclick=()=>project(x.dataset.searchProject));});}}
  render();
  document.addEventListener('click',e=>{const t=e.target.closest('[data-task]');if(t)taskView(t.dataset.task);});
})();
